<div class="wrap"><div class="page-title-row"><div><h2>Clientes</h2><p>Cadastro automático criado a partir dos pedidos.</p></div><b><?= count($customers) ?> clientes</b></div><div class="customer-table"><div class="ct-head"><span>Cliente</span><span>Contato / endereço</span><span>Pedidos</span><span>Total comprado</span><span>Último pedido</span></div><?php foreach($customers as $c): ?><div class="ct-row"><span><b><?= e($c['nome']) ?></b></span><span><?= e($c['telefone']) ?><small><?= e(trim($c['endereco'].' · '.$c['bairro'],' ·')) ?></small></span><span><?= (int)$c['pedidos'] ?></span><span><?= money($c['total_gasto']) ?></span><span><?= e($c['ultimo_pedido']) ?></span></div><?php endforeach; ?><?php if(!$customers): ?><p>Nenhum cliente cadastrado ainda.</p><?php endif; ?></div></div>
